"""Find Peak Element — walk uphill with binary search.

nums[-1] and nums[n] are treated as -infinity, so an ascending slope always has
a peak to its right.

Time: O(log n)   Space: O(1)
"""
from typing import List


class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < nums[mid + 1]:
                lo = mid + 1
            else:
                hi = mid
        return lo
